        //client-1 creates a table and views
        createTable(conn1, tableName);
        createView(conn1, tableName, viewName1);
        createView(conn1, viewName1, viewName2);
        //client-2 populates its cache, 1 getTable RPC each for table, view1, view2
        query(conn2, viewName2);
        Mockito.verify(spyCqs2, Mockito.times(1)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(tableName)), anyLong(), anyLong());
        Mockito.verify(spyCqs2, Mockito.times(1)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(viewName1)), anyLong(), anyLong());
        Mockito.verify(spyCqs2, Mockito.times(1)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(viewName2)), anyLong(), anyLong());
        //client-1 alters first level view
        alterViewAddColumn(conn1, viewName1, "col3");
        //client-2 upserts into second level view
        //verify there was a getTable RPC for the view and all its ancestors
        //verify that the client got a StaleMetadataCacheException
        upsert(conn2, viewName2, true);
        Mockito.verify(spyCqs2, Mockito.times(2)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(tableName)), anyLong(), anyLong());
        Mockito.verify(spyCqs2, Mockito.times(2)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(viewName1)), anyLong(), anyLong());
        Mockito.verify(spyCqs2, Mockito.times(2)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(viewName2)), anyLong(), anyLong());
        Assert.assertEquals("Client should have encountered a StaleMetadataCacheException", 1, GlobalClientMetrics.GLOBAL_CLIENT_STALE_METADATA_CACHE_EXCEPTION_COUNTER.getMetric().getValue());
        //client-2 upserts into first level view
        //verify no getTable RPCs
        //verify that the client did not get a StaleMetadataCacheException
        upsert(conn2, viewName1, true);
        Mockito.verify(spyCqs2, Mockito.times(2)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(tableName)), anyLong(), anyLong());
        Mockito.verify(spyCqs2, Mockito.times(2)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(viewName1)), anyLong(), anyLong());
        Mockito.verify(spyCqs2, Mockito.times(2)).getTable(eq(null), any(byte[].class), eq(PVarchar.INSTANCE.toBytes(viewName2)), anyLong(), anyLong());
        Assert.assertEquals("Client should not have encountered another StaleMetadataCacheException", 1, GlobalClientMetrics.GLOBAL_CLIENT_STALE_METADATA_CACHE_EXCEPTION_COUNTER.getMetric().getValue());
    }
}

