/**
 * Test that client always refreshes its cache for DDL operations.
 * create view -> refresh base table
 * create child view -> refresh parent view and base table
 * add/drop column on table -> refresh table
 * add/drop column on view -> refresh view and base table
 */
@Test
public void testCacheUpdatedBeforeDDLOperations() throws Exception {
    Properties props = PropertiesUtil.deepCopy(TEST_PROPERTIES);
    String url1 = QueryUtil.getConnectionUrl(props, config, "client1");
    String tableName = generateUniqueName();
    String indexName = generateUniqueName();
    String viewName = generateUniqueName();
    String childViewName = generateUniqueName();
    int numTableRPCs = 0, numViewRPCs = 0;
    ConnectionQueryServices spyCqs1 = Mockito.spy(driver.getConnectionQueryServices(url1, props));
    try (Connection conn1 = spyCqs1.connect(url1, props)) {
        // create table
        createTable(conn1, tableName);
        // create index, getTable RPCs for base table
        createIndex(conn1, tableName, indexName, "v2");
        // getting current time,
        // create index(compile+execute),
        // alter index state after building(compile+execute)
        numTableRPCs += 5;
        assertNumGetTableRPC(spyCqs1, tableName, numTableRPCs);
        // create a view, getTable RPC for base table
        createView(conn1, tableName, viewName);
        numTableRPCs++;
        assertNumGetTableRPC(spyCqs1, tableName, numTableRPCs);
        // create a child view, getTable RPC for parent view and base table
        createView(conn1, viewName, childViewName);
        numTableRPCs++;
        numViewRPCs++;
        assertNumGetTableRPC(spyCqs1, tableName, numTableRPCs);
        assertNumGetTableRPC(spyCqs1, viewName, numViewRPCs);
        // add and drop column, 2 getTable RPCs for base table
        alterTableAddColumn(conn1, tableName, "newcol1");
        numTableRPCs++;
        alterTableDropColumn(conn1, tableName, "newcol1");
        numTableRPCs++;
        assertNumGetTableRPC(spyCqs1, tableName, numTableRPCs);
        // add and drop column, 2 getTable RPCs for view
        alterViewAddColumn(conn1, viewName, "newcol2");
        numViewRPCs++;
        numTableRPCs++;
        alterViewDropColumn(conn1, viewName, "newcol2");
        numViewRPCs++;
        numTableRPCs++;
        assertNumGetTableRPC(spyCqs1, viewName, numViewRPCs);
        assertNumGetTableRPC(spyCqs1, tableName, numTableRPCs);
    }
}

private void testTableWithSameSchema(boolean notExists, boolean sameClient) throws Exception {
    // use a spyed ConnectionQueryServices so we can verify calls to getTable
    ConnectionQueryServices connectionQueryServices = Mockito.spy(driver.getConnectionQueryServices(getUrl(), PropertiesUtil.deepCopy(TEST_PROPERTIES)));
    Properties props = new Properties();
    props.putAll(PhoenixEmbeddedDriver.DEFAULT_PROPS.asMap());
    try (Connection conn1 = connectionQueryServices.connect(getUrl(), props);
        Connection conn2 = sameClient ? conn1 : connectionQueryServices.connect(getUrl(), props)) {
        String metricTableName = generateUniqueName();
        String viewName = generateUniqueName();
        String metricIdSeqTableName = generateUniqueName();
        // create sequence for auto partition
        conn1.createStatement().execute("CREATE SEQUENCE " + metricIdSeqTableName + " CACHE 1");
        // create base table
        conn1.createStatement().execute("CREATE TABLE " + metricTableName + "(metricId INTEGER NOT NULL, metricVal DOUBLE, CONSTRAINT PK PRIMARY KEY(metricId))" + " APPEND_ONLY_SCHEMA = true, UPDATE_CACHE_FREQUENCY=1, AUTO_PARTITION_SEQ=" + metricIdSeqTableName);
        // create view
        String ddl = "CREATE VIEW " + (notExists ? "IF NOT EXISTS " : "") + viewName + " ( hostName varchar NOT NULL, tagName varChar" + " CONSTRAINT HOSTNAME_PK PRIMARY KEY (hostName))" + " AS SELECT * FROM " + metricTableName + " UPDATE_CACHE_FREQUENCY=300000";
        conn1.createStatement().execute(ddl);
        conn1.createStatement().execute("UPSERT INTO " + viewName + "(hostName, metricVal) VALUES('host1', 1.0)");
        conn1.commit();
        reset(connectionQueryServices);
        // execute same create ddl
        try {
            conn2.createStatement().execute(ddl);
            if (!notExists) {
                fail("Create Table should fail");
            }
        } catch (TableAlreadyExistsException e) {
            if (notExists) {
                fail("Create Table should not fail");
            }
        }
        // verify getTable rpcs
        verify(connectionQueryServices, never()).getTable((PName) isNull(), AdditionalMatchers.aryEq(new byte[0]), AdditionalMatchers.aryEq(Bytes.toBytes(viewName)), anyLong(), anyLong());
        // verify no create table rpcs
        verify(connectionQueryServices, never()).createTable(anyList(), any(byte[].class), any(PTableType.class), anyMap(), anyList(), any(byte[][].class), eq(false), eq(false), eq(false), any(PTable.class));
        reset(connectionQueryServices);
        // execute alter table ddl that adds the same column
        ddl = "ALTER VIEW " + viewName + " ADD " + (notExists ? "IF NOT EXISTS" : "") + " tagName varchar";
        try {
            conn2.createStatement().execute(ddl);
            if (!notExists) {
                fail("Alter Table should fail");
            }
        } catch (ColumnAlreadyExistsException e) {
            if (notExists) {
                fail("Alter Table should not fail");
            }
        }
        // if not verify exists is true one call to add column table with empty mutation list (which does not make a rpc)
        // else verify no add column calls
        verify(connectionQueryServices, notExists ? times(1) : never()).addColumn(eq(Collections.<Mutation>emptyList()), any(), any(), any(), anyMap(), anySet(), anyList());
        // upsert one row
        conn2.createStatement().execute("UPSERT INTO " + viewName + "(hostName, metricVal) VALUES('host2', 2.0)");
        conn2.commit();
        // verify data in base table
        ResultSet rs = conn2.createStatement().executeQuery("SELECT * from " + metricTableName);
        assertTrue(rs.next());
        assertEquals(1, rs.getInt(1));
        assertEquals(1.0, rs.getDouble(2), 1e-6);
        assertTrue(rs.next());
        assertEquals(1, rs.getInt(1));
        assertEquals(2.0, rs.getDouble(2), 1e-6);
        assertFalse(rs.next());
        // verify data in view
        rs = conn2.createStatement().executeQuery("SELECT * from " + viewName);
        assertTrue(rs.next());
        assertEquals(1, rs.getInt(1));
        assertEquals(1.0, rs.getDouble(2), 1e-6);
        assertEquals("host1", rs.getString(3));
        assertTrue(rs.next());
        assertEquals(1, rs.getInt(1));
        assertEquals(2.0, rs.getDouble(2), 1e-6);
        assertEquals("host2", rs.getString(3));
        assertFalse(rs.next());
    }
}

